namespace zar {
bool CKey::Write(CZAR* archive)
	{
		archive->Securify(m_name, 4);
		archive->m_pFile->fwrite(m_name, 4);
		archive->Unsecurify(m_name, 4);

		archive->Securify(&m_offset, 4);
		archive->m_pFile->fwrite(&m_offset, 4);
		archive->Unsecurify(&m_offset, 4);

		archive->Securify(&m_size, 4);
		archive->m_pFile->fwrite(&m_size, 4);
		archive->Unsecurify(&m_size, 4);

		archive->Securify(this, 4);
		archive->m_pFile->fwrite(this, 4);
		archive->Unsecurify(this, 4);

		for (auto it = begin(); it != end(); ++it)
		{
			CKey* key = *it;
			key->Write(archive);
		}

		return true;
	}
}

/* @socom-skeleton body Read__Q23zar4CKeyFPQ23zar4CZARP3CIOi */
bool zar::CKey::Read(zar::CZAR *archive, CIO *io, int strbase)
{
	/* 0x1dc1d0: a 16-byte record (name offset, data offset, size, child count), then
	 * the children depth first. The root keeps its own name. */
	struct KEY
	{
		s32 m_name;
		s32 m_offset;
		s32 m_size;
		u32 m_count;
	} rec;

	io->fread(&rec, sizeof(KEY));

	if (archive->m_root != this)
	{
		m_name = (char*)(rec.m_name + strbase);
		m_offset = rec.m_offset;
		m_size = rec.m_size;
	}

	for (u32 count = rec.m_count; count != 0; count--)
	{
		CKey* child = archive->NewKey(NULL);
		child->Read(archive, io, strbase);
		push_back(child);
	}

	return true;
}

